    val kBigInt = BigInteger.valueOf(k - 1) // Convert to 0-based index
    val permutation = LongArray(n.toInt())
    var remaining = kBigInt

    for (i in 0 until n.toInt()) {
        val fact = factorial(n - i - 1)
        val index = remaining.divide(fact).toInt()
        permutation[i] = numbers.removeAt(index)
        remaining = remaining.remainder(fact)
    }

    return permutation
}

fun generateLuckyNumbers(n: Long): Set<Long> {
    val luckyNumbers = mutableSetOf<Long>()
    val queue = ArrayDeque<Long>()
    queue.add(4)
    queue.add(7)

    while (queue.isNotEmpty()) {
        val num = queue.removeFirst()
        if (num > n) continue
        luckyNumbers.add(num)
        queue.add(num * 10 + 4)
        queue.add(num * 10 + 7)
    }

    return luckyNumbers
}
