import java.math.BigInteger

fun main() {
    val (nStr, kStr) = readLine()!!.split(" ")
    val n = nStr.toLong()
    val k = kStr.toBigInteger()

    // Calculate factorial of (n-1) to check if k exceeds the number of permutations
