    if (k > maxFactorial) {
        println(-1)
        return
    }

    // Generate the k-th permutation (1-based index)
    val perm = generateKthPermutation(n, k)

    // Count positions where both index (1-based) and value are lucky numbers
    var count = 0
    for (i in 0 until n) {
        val pos = (i + 1).toString()
        val valStr = perm[i].toString()
        if (isLucky(pos) && isLucky(valStr)) {
            count++
        }
    }
    println(count)
}

fun factorial(n: Long): BigInteger {
    var result = BigInteger.ONE
    for (i in 1..n) {
        result = result.multiply(BigInteger.valueOf(i))
    }
    return result
}

fun generateKthPermutation(n: Long, k: BigInteger): List<Long> {
    val numbers = (1..n).toMutableList()
    val perm = mutableListOf<Long>()
    var currentK = k - BigInteger.ONE // Convert to 0-based index

    for (i in 0 until n) {
        val fact = factorial(n - i - 1)
        val index = currentK.divide(fact).toInt()
        perm.add(numbers.removeAt(index))
        currentK = currentK.remainder(fact)
    }
    return perm
}

fun isLucky(s: String): Boolean {
    for (c in s) {
        if (c != '4' && c != '7') return false
    }
    return true
}
